
const sessionDetail = JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(""), (c) => c.charCodeAt(0))));
window.__TAURI__ = { core: { invoke: async (cmd, args) => {
  if (cmd === "sessions_list") return [{ sessionId: "demo", sourceTool: "codex", cwd: "F:/demo", createdAt: "2026-08-14T00:00:00Z", updatedAt: "2026-08-14T01:00:00Z", title: "demo session", messageCount: 4 }];
  if (cmd === "sessions_get") return sessionDetail;
  if (cmd === "daemon_status") return { running: false, pid: null };
  return null;
} } };

  const { invoke } = window.__TAURI__.core;
  const api = {
    list: (filter) => invoke('sessions_list', { filter }),
    get: (id) => invoke('sessions_get', { sessionId: id }),
    remove: (id) => invoke('sessions_delete', { sessionId: id }),
    restore: (id, target) => invoke('sessions_restore', { sessionId: id, target }),
    daemonStatus: () => invoke('daemon_status'),
    daemonToggle: () => invoke('daemon_toggle'),
  };
  const state = { tool: 'all', query: '', sessions: [], selectedId: null, fingerprint: '' };

  const $ = (id) => document.getElementById(id);
  const listEl = $('sessionList');
  const emptyEl = $('emptyState');
  const bodyEl = $('detailBody');

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  }

  function relTime(iso) {
    const t = new Date(iso).getTime();
    if (!Number.isFinite(t)) return '';
    const s = Math.max(0, (Date.now() - t) / 1000);
    if (s < 60) return '刚刚';
    if (s < 3600) return Math.floor(s / 60) + ' 分钟前';
    if (s < 86400) return Math.floor(s / 3600) + ' 小时前';
    if (s < 86400 * 30) return Math.floor(s / 86400) + ' 天前';
    return new Date(t).toLocaleDateString();
  }

  function fmtTime(iso) {
    const d = new Date(iso);
    return Number.isFinite(d.getTime()) ? d.toLocaleString() : iso;
  }

  let toastTimer;
  function toast(message, ok = true) {
    const el = $('toast');
    el.textContent = message;
    el.className = 'show' + (ok ? '' : ' err');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => { el.className = ''; }, 5200);
  }

  async function loadSessions(keepScroll = true) {
    const scroll = listEl.scrollTop;
    try {
      const sessions = await api.list({ tool: state.tool === 'all' ? undefined : state.tool, query: state.query });
      state.sessions = sessions;
      $('countPill').textContent = sessions.length + ' 个会话';
      const fp = JSON.stringify(sessions.map((s) => s.sessionId + s.updatedAt));
      if (fp !== state.fingerprint) {
        state.fingerprint = fp;
        renderList();
      }
      if (keepScroll) listEl.scrollTop = scroll;
      if (state.selectedId && !sessions.some((s) => s.sessionId === state.selectedId)) {
        clearDetail();
      }
    } catch (e) {
      toast('加载会话失败: ' + (e.message || e), false);
    }
  }

  function renderList() {
    if (!state.sessions.length) {
      listEl.innerHTML = '<div class="empty">没有匹配的会话</div>';
      return;
    }
    listEl.innerHTML = state.sessions.map((s) => [
      '<div class="card' + (s.sessionId === state.selectedId ? ' active' : '') + '" data-id="' + escapeHtml(s.sessionId) + '">',
      '  <div class="title">' + escapeHtml(s.title) + '</div>',
      '  <div class="meta">',
      '    <span class="badge ' + s.sourceTool + '">' + (s.sourceTool === 'codex' ? 'Codex' : 'Claude') + '</span>',
      '    <span class="count">' + s.messageCount + ' 条消息</span>',
      '    <span class="rel" title="' + escapeHtml(fmtTime(s.updatedAt)) + '">' + relTime(s.updatedAt) + '</span>',
      '  </div>',
      '  <div class="cwd" title="' + escapeHtml(s.cwd) + '">' + escapeHtml(s.cwd) + '</div>',
      '</div>',
    ].join('\n')).join('\n');
    for (const card of listEl.querySelectorAll('.card')) {
      card.addEventListener('click', () => selectSession(card.dataset.id));
    }
  }

  function clearDetail() {
    state.selectedId = null;
    emptyEl.style.display = 'grid';
    bodyEl.classList.remove('open');
    bodyEl.innerHTML = '';
    renderList();
  }

  async function selectSession(id) {
    state.selectedId = id;
    renderList();
    let session;
    try {
      session = await api.get(id);
    } catch (e) {
      toast('读取会话失败: ' + (e.message || e), false);
      return;
    }
    renderDetail(session);
  }

  function truncate(s, n) {
    s = String(s == null ? '' : s);
    return s.length > n ? s.slice(0, n) + '\n… (截断, 共 ' + s.length + ' 字符)' : s;
  }

  function sessionTitle(session) {
    const firstUser = session.messages.find((m) => m.role === 'user' && m.text && m.text.trim());
    const t = firstUser ? firstUser.text.trim().replace(/\s+/g, ' ') : '(空会话)';
    return t.length > 120 ? t.slice(0, 120) + '…' : t;
  }

  function renderDetail(session) {
    emptyEl.style.display = 'none';
    bodyEl.classList.add('open');
    const toolLabel = session.sourceTool === 'codex' ? 'Codex' : 'Claude';
    const otherTool = session.sourceTool === 'codex' ? 'claude' : 'codex';
    const otherLabel = session.sourceTool === 'codex' ? 'Claude' : 'Codex';
    const toolCalls = session.messages.reduce((n, m) => n + ((m.toolCalls && m.toolCalls.length) || 0), 0);
    const title = sessionTitle(session);

    bodyEl.innerHTML = [
      '<div class="detail-head">',
      '  <h1>' + escapeHtml(title) + '</h1>',
      '  <div class="detail-sub">',
      '    <span class="badge ' + session.sourceTool + '">' + toolLabel + '</span>',
      '    <span>' + session.messages.length + ' 条消息 · ' + toolCalls + ' 次工具调用</span>',
      '    <span>更新于 ' + escapeHtml(fmtTime(session.updatedAt)) + '</span>',
      '  </div>',
      '  <div class="detail-sub"><span class="cwd">' + escapeHtml(session.cwd) + '</span></div>',
      '  <div class="detail-sub"><span class="sid" id="sidCopy" title="点击复制会话 ID">' + escapeHtml(session.sessionId) + '</span></div>',
      '  <div class="actions">',
      '    <button class="btn primary" id="btnRestoreCross">恢复到 ' + otherLabel + ' 继续对话</button>',
      '    <button class="btn" id="btnRestoreSame">复制回 ' + toolLabel + '</button>',
      '    <button class="btn danger" id="btnDelete">删除镜像</button>',
      '  </div>',
      '</div>',
      '<div id="conversation"></div>',
    ].join('\n');

    $('sidCopy').addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(session.sessionId);
        toast('会话 ID 已复制');
      } catch {
        const ta = document.createElement('textarea');
        ta.value = session.sessionId;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
        toast('会话 ID 已复制');
      }
    });

    $('btnRestoreCross').addEventListener('click', (e) => doRestore(session.sessionId, otherTool, e.target));
    $('btnRestoreSame').addEventListener('click', (e) => doRestore(session.sessionId, session.sourceTool, e.target));
    $('btnDelete').addEventListener('click', async () => {
      if (!confirm('确定删除这条会话镜像吗?\n\n' + title + '\n\n只会删除 session-loom 的镜像数据, 不影响原始会话文件。')) return;
      try {
        await api.remove(session.sessionId);
        toast('镜像已删除');
        state.fingerprint = '';
        clearDetail();
        loadSessions(false);
      } catch (e) {
        toast('删除失败: ' + (e.message || e), false);
      }
    });

    const conv = $('conversation');
    const frag = document.createDocumentFragment();
    for (const m of session.messages) {
      const hasText = m.text && m.text.trim();
      const hasTools = m.toolCalls && m.toolCalls.length;
      if (!hasText && !hasTools) continue;
      const div = document.createElement('div');
      div.className = 'msg ' + m.role;
      let html = '<div class="role">' + (m.role === 'user' ? '用户' : '助手') + '</div>';
      if (hasText) html += '<div class="text">' + escapeHtml(m.text) + '</div>';
      for (const tc of m.toolCalls || []) {
        html += '<details class="tool"><summary>' + escapeHtml(tc.name) + '</summary>';
        html += '<pre>' + escapeHtml(truncate(JSON.stringify(tc.input, null, 2) || '', 4000)) + '</pre>';
        if (tc.output) html += '<pre>' + escapeHtml(truncate(tc.output, 4000)) + '</pre>';
        html += '</details>';
      }
      div.innerHTML = html;
      frag.appendChild(div);
    }
    conv.innerHTML = '';
    conv.appendChild(frag);
    if (!conv.children.length) {
      conv.innerHTML = '<div class="empty">这个会话没有可显示的对话内容</div>';
    }
  }

  async function doRestore(sessionId, target, btn) {
    btn.disabled = true;
    const old = btn.textContent;
    btn.textContent = '恢复中…';
    try {
      const res = await api.restore(sessionId, target);
      toast(res.message, res.ok);
    } catch (e) {
      toast('恢复失败: ' + (e.message || e), false);
    } finally {
      btn.disabled = false;
      btn.textContent = old;
    }
  }

  async function refreshDaemon() {
    try {
      const s = await api.daemonStatus();
      $('daemonPill').classList.toggle('on', !!s.running);
      $('daemonText').textContent = s.running ? '守护进程 · 运行中 (pid ' + s.pid + ')' : '守护进程 · 已停止';
    } catch {
      $('daemonText').textContent = '守护进程 · 未知';
    }
  }

  $('daemonPill').addEventListener('click', async () => {
    try {
      await api.daemonToggle();
      await refreshDaemon();
    } catch (e) {
      toast('守护进程操作失败: ' + (e.message || e), false);
    }
  });

  let searchTimer;
  $('search').addEventListener('input', (e) => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      state.query = e.target.value;
      state.fingerprint = '';
      loadSessions(false);
    }, 220);
  });

  for (const tab of document.querySelectorAll('.tab')) {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.tab').forEach((t) => t.classList.remove('active'));
      tab.classList.add('active');
      state.tool = tab.dataset.tool;
      state.fingerprint = '';
      loadSessions(false);
    });
  }

  setInterval(() => {
    if (!document.hidden) {
      loadSessions();
      refreshDaemon();
    }
  }, 3000);

  loadSessions(false);
  refreshDaemon();
